-- Ensina-me: deepen Stage I-IV internship materials.
-- Idempotent content migration, aligned with supervised progressive practice.

update public.material_sections ms
set content=v.content,updated_at=now()
from (values
($$Estágio Curricular Supervisionado I$$,$$Observação e reconhecimento do campo$$,1,$$O núcleo de observação e reconhecimento do campo é registrar o contexto antes de propor intervenções e distinguir descrição de interpretação. O estágio deve ser tratado como experiência de formação: observar, participar ou atuar precisa estar ligado a objetivos de aprendizagem profissional.$$),
($$Estágio Curricular Supervisionado I$$,$$Observação e reconhecimento do campo$$,2,$$Antes de agir, pergunte como reduzir o estágio a uma visita e produzir relatos baseados apenas em impressões. A decisão ganha qualidade quando considera o planejamento da escola, as características da turma e as orientações do professor ou supervisor.$$),
($$Estágio Curricular Supervisionado I$$,$$Observação e reconhecimento do campo$$,3,$$Para estudar esse tema, diferencie evidência de impressão. Registros, falas, produções dos estudantes e observações datadas permitem revisar a interpretação e tornam a experiência analisável depois.$$),
($$Estágio Curricular Supervisionado I$$,$$Observação e reconhecimento do campo$$,4,$$Imagine uma situação do campo relacionada ao tópico. O estagiário precisa identificar o problema, considerar as restrições reais e justificar sua escolha, em vez de aplicar uma atividade pronta sem adaptação.$$),
($$Estágio Curricular Supervisionado I$$,$$Observação e reconhecimento do campo$$,5,$$Uma análise formativa procura responder: o que aconteceu, por que pode ter acontecido e o que faria diferente numa próxima oportunidade? Essa sequência transforma a experiência em aprendizagem profissional.$$),
($$Estágio Curricular Supervisionado I$$,$$Observação e reconhecimento do campo$$,6,$$Um erro frequente é undefined. Isso enfraquece o caráter educativo do estágio porque substitui investigação e reflexão por rotina, opinião ou atuação sem critério.$$),
($$Estágio Curricular Supervisionado I$$,$$Observação e reconhecimento do campo$$,7,$$O aprofundamento acontece quando o estagiário conecta a experiência às ideias estudadas na universidade. A teoria não serve apenas para citar autores; serve para criar perguntas e interpretar situações do campo.$$),
($$Estágio Curricular Supervisionado I$$,$$Observação e reconhecimento do campo$$,8,$$Na prática, registre uma hipótese de trabalho, realize a ação sob acompanhamento, colete evidências e converse sobre os resultados. O objetivo é aprender a ajustar decisões, não demonstrar perfeição.$$),
($$Estágio Curricular Supervisionado I$$,$$Observação e reconhecimento do campo$$,9,$$A síntese pode reunir contexto, objetivo, ação, evidências, devolutivas e aprendizagem. Esse encadeamento mostra como a experiência contribuiu para desenvolver conhecimentos profissionais específicos.$$),
($$Estágio Curricular Supervisionado I$$,$$Observação e reconhecimento do campo$$,10,$$Para revisar, explique observação e reconhecimento do campo em suas próprias palavras e dê um exemplo concreto do campo. Em seguida, indique qual evidência você precisaria registrar para avaliar a qualidade da sua decisão.$$),
