)v(discipline,topic,position,content)
join public.disciplines d on d.name=v.discipline
join public.topics t on t.discipline_id=d.id and t.name=v.topic
join public.materials m on m.topic_id=t.id
where ms.material_id=m.id and ms.position=v.position;

insert into public.material_citations(material_id,source_id,citation_label)
select m.id,s.id,x.label
from (values
 ('Estágio Curricular Supervisionado I','Resolução CNE/CP nº 4, de 29 de maio de 2024 — Diretrizes Curriculares Nacionais para a Formação Inicial','CNE/CP 4/2024 — formação inicial'),
 ('Estágio Curricular Supervisionado II','Resolução CNE/CP nº 4, de 29 de maio de 2024 — Diretrizes Curriculares Nacionais para a Formação Inicial','CNE/CP 4/2024 — progressão e supervisão'),
 ('Estágio Curricular Supervisionado III','Resolução CNE/CP nº 4, de 29 de maio de 2024 — Diretrizes Curriculares Nacionais para a Formação Inicial','CNE/CP 4/2024 — prática e devolutiva'),
 ('Estágio Curricular Supervisionado IV','Resolução CNE/CP nº 4, de 29 de maio de 2024 — Diretrizes Curriculares Nacionais para a Formação Inicial','CNE/CP 4/2024 — autonomia acompanhada'),
 ('Estágio Curricular Supervisionado I','Resolução CNE/CP nº 1, de 15 de maio de 2006 — Diretrizes Curriculares Nacionais para o Curso de Graduação em Pedagogia','DCN Pedagogia'),
 ('Estágio Curricular Supervisionado II','Resolução CNE/CP nº 1, de 15 de maio de 2006 — Diretrizes Curriculares Nacionais para o Curso de Graduação em Pedagogia','DCN Pedagogia'),
 ('Estágio Curricular Supervisionado III','Resolução CNE/CP nº 1, de 15 de maio de 2006 — Diretrizes Curriculares Nacionais para o Curso de Graduação em Pedagogia','DCN Pedagogia'),
 ('Estágio Curricular Supervisionado IV','Resolução CNE/CP nº 1, de 15 de maio de 2006 — Diretrizes Curriculares Nacionais para o Curso de Graduação em Pedagogia','DCN Pedagogia')
) x(discipline,source_title,label)
join public.disciplines d on d.name=x.discipline
join public.topics t on t.discipline_id=d.id
join public.materials m on m.topic_id=t.id
join public.sources s on s.title=x.source_title
where not exists(select 1 from public.material_citations mc where mc.material_id=m.id and mc.source_id=s.id);